"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["55978"],{53511(e){e.exports=JSON.parse('{"id":"F479","slug":"ai-fraud-model-value","name":"AI Fraud Model: Net Value of Alerts","subject":"Fintech & Digital Finance","section":"Fintech","topic":"AI in banking, trading and advice","level":"Intermediate","aliases":["AI in banking, trading and advice","fraud detection model","false positives","alert review cost","precision and recall"],"formula":{"latex":"\\\\text{Net}=TP\\\\times L-(TP+FP)\\\\times c,\\\\quad \\\\text{Precision}=\\\\frac{TP}{TP+FP},\\\\ \\\\text{Recall}=\\\\frac{TP}{TP+FN}","also":[],"text":"Fraud stopped = true alerts x average loss per fraud; Review cost = all alerts (true + false) x cost to review one alert; Net value = fraud stopped - review cost; Missed fraud = missed cases x average loss; Precision = true alerts / all alerts; Recall = true alerts / all frauds"},"symbols":[{"symbol":"TP","meaning":"Alerts that were real fraud","unit":"count"},{"symbol":"FP","meaning":"Alerts that were not fraud (wasted review)","unit":"count"},{"symbol":"FN","meaning":"Frauds the model missed","unit":"count"},{"symbol":"L","meaning":"Average loss per fraud case","unit":"money"},{"symbol":"c","meaning":"Cost to review one alert","unit":"money"}],"when_to_use":"Use it to judge a machine-learning model by money, not accuracy alone. A model that flags many harmless transactions costs analyst time and annoys customers; one that is too cautious lets fraud through. Choose the alert threshold where the net value is highest. The same logic applies to credit models and trading signals, with their own cost of an error.","worked_example":{"problem":"In a month a fraud model raised 800 alerts: 420 were real fraud and 380 were not. It missed 80 frauds. The average fraud costs 1,200 and an alert costs 25 to review.","inputs":{"tp":420,"fp":380,"fn":80,"l":1200,"c":25},"steps":[{"label":"Fraud stopped","working":"420 x 1200","value":"504,000.00"},{"label":"Review cost","working":"(420+380) x 25","value":"20,000.00"},{"label":"Net value","working":"504000-20000","value":"484,000.00"},{"label":"Missed fraud","working":"80 x 1200","value":"96,000.00"},{"label":"Precision","working":"420 / (420+380)","value":"52.5%"},{"label":"Recall","working":"420 / (420+80)","value":"84.0%"}],"answer":"The model stopped 504,000.00 of fraud and cost 20,000.00 in reviews, a net value of 484,000.00. It missed 96,000.00 of fraud. Precision is 52.5% and recall is 84.0%."},"calculator":{"available":true,"inputs":[{"id":"tp","label":"True alerts","unit":"count","type":"number","default":420,"hint":""},{"id":"fp","label":"False alerts","unit":"count","type":"number","default":380,"hint":""},{"id":"fn","label":"Missed frauds","unit":"count","type":"number","default":80,"hint":""},{"id":"l","label":"Average loss per fraud","unit":"money","type":"number","default":1200,"hint":""},{"id":"c","label":"Cost to review one alert","unit":"money","type":"number","default":25,"hint":""}],"checks":[{"expr":"tp+fp>0 and tp+fn>0","message":"Enter some alerts and some frauds."}],"steps":[{"id":"saved","label":"Fraud stopped","expr":"tp*l","format":"money"},{"id":"rev","label":"Review cost","expr":"(tp+fp)*c","format":"money"},{"id":"net","label":"Net value","expr":"saved-rev","format":"money"},{"id":"miss","label":"Missed fraud","expr":"fn*l","format":"money"},{"id":"prec","label":"Precision","expr":"tp/(tp+fp)","format":"pct1"},{"id":"rec","label":"Recall","expr":"tp/(tp+fn)","format":"pct1"}],"results":["net","miss","prec","rec"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"saved":504000,"rev":20000,"net":484000,"miss":96000,"prec":0.525,"rec":0.84}},"finder":{"finds":"What a detection model is worth in money","needs":"Alert counts, missed frauds, loss per fraud, review cost"},"related":[{"slug":"classification-metrics","name":"Classification Metrics: Precision, Recall and F1"},{"slug":"forecast-calibration","name":"Forecast Calibration and Brier Score"},{"slug":"bayes-theorem","name":"Bayes\' Theorem"}],"related_ids":["F417","F421","F056"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Net</mtext><mo>=</mo><mi>T</mi><mi>P</mi><mo>\xd7</mo><mi>L</mi><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>P</mi><mo stretchy=\\"false\\">)</mo><mo>\xd7</mo><mi>c</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Precision</mtext><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>P</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mtext>\xa0Recall</mtext><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>N</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Net}=TP\\\\times L-(TP+FP)\\\\times c,\\\\quad \\\\text{Precision}=\\\\frac{TP}{TP+FP},\\\\ \\\\text{Recall}=\\\\frac{TP}{TP+FN}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"age-based-allocation","name":"Age-Based Asset Allocation and Portfolio Risk"},"next":{"slug":"all-in-loan-cost","name":"All-In Cost of a Loan (One Year)"},"lesson":null,"total":522}')}}]);